internal enum CssKeywordSet
{
    Empty,
    MediaOrientation,
    MediaPointer,
    MediaHover,
    MediaDisplayMode,
    MediaPrefersColorScheme,
    MediaPrefersReducedMotion,
    MediaPrefersContrast,
    MediaForcedColors,
    MediaScripting,
}

internal static class CssKeywordLookup
{
    internal static string? Match(ReadOnlySpan<char> input, CssKeywordSet set) => set switch
    {
        CssKeywordSet.Empty => null,
        CssKeywordSet.MediaOrientation => CssMediaOrientationKeywords.Match(input),
        CssKeywordSet.MediaPointer => CssMediaPointerKeywords.Match(input),
        CssKeywordSet.MediaHover => CssMediaHoverKeywords.Match(input),
        CssKeywordSet.MediaDisplayMode => CssMediaDisplayModeKeywords.Match(input),
        CssKeywordSet.MediaPrefersColorScheme => CssMediaPrefersColorSchemeKeywords.Match(input),
        CssKeywordSet.MediaPrefersReducedMotion => CssMediaPrefersReducedMotionKeywords.Match(input),
        CssKeywordSet.MediaPrefersContrast => CssMediaPrefersContrastKeywords.Match(input),
        CssKeywordSet.MediaForcedColors => CssMediaForcedColorsKeywords.Match(input),
        CssKeywordSet.MediaScripting => CssMediaScriptingKeywords.Match(input),
        _ => throw new ArgumentOutOfRangeException(nameof(set))
    };
}
